import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    private static final BufferedReader reader =
            new BufferedReader(new InputStreamReader(System.in));

    static String readLn() throws IOException {
        return Objects.requireNonNull(reader.readLine());
    }

    static int readInt() throws IOException {
        return Integer.parseInt(readLn());
    }

    static List<String> readStrings() throws IOException {
        return Arrays.asList(readLn().split(" "));
    }

    static List<Integer> readInts() throws IOException {
        return readStrings().stream()
                .map(Integer::parseInt)
                .collect(Collectors.toList());
    }

    static int findLissPos() throws IOException {
        String stones = readLn();
        String instructions = readLn();
        int curPos = 0;

        for (int i = 0; i < instructions.length(); i++) {
            if (stones.charAt(curPos) == instructions.charAt(i)) {
                curPos++;
            }
        }

        curPos++;
        return curPos;
    }

    public static void main(String[] args) throws IOException {
        System.out.print(findLissPos());
    }
}

